export class ForgeView{
 constructor(canvas,settings){this.settings=settings;this.canvas=canvas;this.renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=THREE.PCFSoftShadowMap;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.05;this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.scene=new THREE.Scene();this.scene.fog=new THREE.FogExp2(0x6fabb7,.0045);this.camera=new THREE.PerspectiveCamera(70,innerWidth/innerHeight,.1,700);this.camera.rotation.order='YXZ';this.camera.position.set(0,9,24);this.yaw=0;this.pitch=-.1;this.meshes=new Map();this.avatars=new Map();this.bondMeshes=[];this.effects=[];this.time=0;this.lastEvent=0;this.target=null;this.ray=new THREE.Raycaster();this.ray.far=45;this.solid=[];this.buildEnvironment();this.geos=[new THREE.BoxGeometry(1,1,1),new THREE.IcosahedronGeometry(.65,1),new THREE.OctahedronGeometry(.8,0)];this.mats=MATERIALS.map(m=>new THREE.MeshStandardMaterial({color:m.color,roughness:m.id==='stone'?.88:.3,metalness:m.id==='gold'?.7:.25,emissive:m.color,emissiveIntensity:m.emissive,transparent:m.id==='glass',opacity:m.id==='glass'?.65:1}));this.coreMat=new THREE.MeshStandardMaterial({color:0x13382d,metalness:.8,roughness:.2,emissive:0x00ffb0,emissiveIntensity:1.5});this.seedMat=new THREE.MeshStandardMaterial({color:0x90ffe0,emissive:0x00ffac,emissiveIntensity:2.2,roughness:.3});this.branchMat=new THREE.MeshStandardMaterial({color:0x153e34,metalness:.3,roughness:.6,emissive:0x14b77c,emissiveIntensity:.25});this.selection=new THREE.Mesh(new THREE.BoxGeometry(1.08,1.08,1.08),new THREE.MeshBasicMaterial({color:0xb5ffe1,wireframe:true,transparent:true,opacity:.7,depthTest:false}));this.selection.visible=false;this.selection.renderOrder=20;this.scene.add(this.selection);
  this.composer=new EffectComposer(this.renderer);this.composer.addPass(new RenderPass(this.scene,this.camera));this.bloom=new UnrealBloomPass(new THREE.Vector2(innerWidth,innerHeight),.6,.5,.85);this.composer.addPass(this.bloom);this.composer.addPass(new OutputPass());this.resize();window.addEventListener('resize',()=>this.resize());this.makeHand();
 }
 resize(){this.renderer.setSize(innerWidth,innerHeight);this.camera.aspect=innerWidth/innerHeight;this.camera.updateProjectionMatrix();this.composer?.setSize(innerWidth,innerHeight);}
 mat(color,roughness=.85){return new THREE.MeshStandardMaterial({color,roughness,flatShading:true});}
 buildEnvironment(){const rr=rng(512);this.hemi=new THREE.HemisphereLight(0xc9f5ff,0x26432d,1.6);this.scene.add(this.hemi);this.sun=new THREE.DirectionalLight(0xffe5bd,3.5);this.sun.position.set(40,100,30);this.sun.castShadow=true;this.sun.shadow.mapSize.set(2048,2048);Object.assign(this.sun.shadow.camera,{left:-100,right:100,top:100,bottom:-100,near:1,far:250});this.sun.shadow.bias=-.0007;this.sun.shadow.normalBias=.15;this.scene.add(this.sun);
  const skyGeo=new THREE.SphereGeometry(450,32,16);this.skyMat=new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:{top:{value:new THREE.Color(0x193c68)},bottom:{value:new THREE.Color(0xd6f3dc)},sunColor:{value:new THREE.Color(0xffcba0)}},vertexShader:'varying vec3 vPos; void main(){vPos=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 vPos;uniform vec3 top;uniform vec3 bottom;uniform vec3 sunColor;void main(){float h=normalize(vPos).y;vec3 col=mix(bottom,top,pow(max(0.,h),.6));float sun=pow(max(0.,dot(normalize(vPos),normalize(vec3(.4,.55,-.6)))),90.);col+=sunColor*sun*1.8;gl_FragColor=vec4(col,1.);}'});this.sky=new THREE.Mesh(skyGeo,this.skyMat);this.scene.add(this.sky);
  const rockMats=[this.mat(0x263f4b),this.mat(0x36535a),this.mat(0x435c63),this.mat(0x1d303e)];const grass=this.mat(0x467c62),edge=this.mat(0x2e524a);for(let idx=0;idx<ISLANDS.length;idx++){const is=ISLANDS[idx],group=new THREE.Group();group.position.set(is.x,is.y,is.z);const top=new THREE.Mesh(new THREE.CylinderGeometry(is.r,is.r*.94,1.2,11),idx===0?this.mat(0x4a7564):grass);top.position.y=-.5;top.receiveShadow=true;top.castShadow=true;group.add(top);this.solid.push(top);const rock=new THREE.Mesh(new THREE.ConeGeometry(is.r*.96,is.r*1.4,9,2),rockMats[idx%4]);rock.rotation.z=Math.PI;rock.position.y=-is.r*.7-.8;rock.castShadow=true;rock.receiveShadow=true;group.add(rock);for(let k=0;k<8;k++){const a=k*Math.PI/4+rr(),radius=is.r*.7;const shard=new THREE.Mesh(new THREE.IcosahedronGeometry(1.7+rr()*3,0),rockMats[(k+idx)%4]);shard.position.set(Math.cos(a)*radius,-2-rr()*8,Math.sin(a)*radius);shard.scale.set(1,2,1);shard.rotation.set(rr(),rr(),rr());shard.castShadow=true;group.add(shard);}const ring=new THREE.Mesh(new THREE.TorusGeometry(is.r*1.01,.045,4,80),new THREE.MeshStandardMaterial({color:0x54ffd0,emissive:0x00b98b,emissiveIntensity:.9}));ring.rotation.x=Math.PI/2;ring.position.y=.15;group.add(ring);
   const bladeGeo=new THREE.ConeGeometry(.13,.7,3);const grassMesh=new THREE.InstancedMesh(bladeGeo,this.mat(0x4d9e70),idx===0?150:70);const dummy=new THREE.Object3D();for(let i=0;i<grassMesh.count;i++){const a=rr()*Math.PI*2,r=Math.sqrt(rr())*(is.r-2);dummy.position.set(Math.cos(a)*r,.4,Math.sin(a)*r);if(idx===0&&r<14)dummy.position.y=-20;dummy.rotation.set(0,rr()*6,rr()*.2);dummy.scale.setScalar(.6+rr());dummy.updateMatrix();grassMesh.setMatrixAt(i,dummy.matrix);}group.add(grassMesh);this.scene.add(group);
   if(idx%2===1){const water=new THREE.Mesh(new THREE.CylinderGeometry(.5,.8,34,6,1,true),new THREE.MeshBasicMaterial({color:0x86e7ed,transparent:true,opacity:.18,side:THREE.DoubleSide,depthWrite:false}));water.position.set(is.x+is.r*.7,is.y-17,is.z);this.scene.add(water);}
  }
  const plaza=new THREE.Mesh(new THREE.CylinderGeometry(14,14,.18,64),this.mat(0x273f3c));plaza.position.y=.25;plaza.receiveShadow=true;this.scene.add(plaza);const ringsMat=new THREE.MeshStandardMaterial({color:0xa5ffe3,emissive:0x00d992,emissiveIntensity:1});for(const r of [8,13.5]){const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.035,4,100),ringsMat);ring.rotation.x=Math.PI/2;ring.position.y=.36;this.scene.add(ring);}for(const x of [-5,5]){const column=new THREE.Mesh(new THREE.BoxGeometry(1,8,1.2),this.mat(0xbed8c9));column.position.set(x,4,-20);column.castShadow=true;this.scene.add(column);}const beam=new THREE.Mesh(new THREE.BoxGeometry(11,1,1.2),this.mat(0xbed8c9));beam.position.set(0,8,-20);beam.castShadow=true;this.scene.add(beam);const light=new THREE.Mesh(new THREE.BoxGeometry(8,.09,1.25),ringsMat);light.position.set(0,7.9,-20);this.scene.add(light);
  this.clouds=new THREE.Group();const cloudMat=new THREE.MeshStandardMaterial({color:0xd3f2ea,transparent:true,opacity:.55,roughness:1,flatShading:true});for(let i=0;i<24;i++){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(8+rr()*15,1),cloudMat);m.position.set((rr()-.5)*420,68+rr()*65,(rr()-.5)*420);m.scale.set(2,.25,1);this.clouds.add(m);}this.scene.add(this.clouds);
  const positions=new Float32Array(1500);for(let i=0;i<500;i++){positions[i*3]=(rr()-.5)*250;positions[i*3+1]=rr()*100-10;positions[i*3+2]=(rr()-.5)*250;}const dustGeo=new THREE.BufferGeometry();dustGeo.setAttribute('position',new THREE.BufferAttribute(positions,3));this.dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0x9bffe0,size:.12,transparent:true,opacity:.45,sizeAttenuation:true}));this.scene.add(this.dust);
 }
 makeHand(){this.hand=new THREE.Group();const mat=new THREE.MeshStandardMaterial({color:0x213c34,metalness:.7,roughness:.3});const gun=new THREE.Mesh(new THREE.CylinderGeometry(.1,.16,.6,6),mat);gun.rotation.x=Math.PI/2;gun.position.set(.34,-.3,-.65);this.hand.add(gun);const ring=new THREE.Mesh(new THREE.TorusGeometry(.12,.018,4,12),new THREE.MeshBasicMaterial({color:0x00e8a5}));ring.position.set(.34,-.3,-.95);this.hand.add(ring);const core=new THREE.Mesh(new THREE.OctahedronGeometry(.07),this.seedMat);core.position.copy(ring.position);this.hand.add(core);this.camera.add(this.hand);this.scene.add(this.camera);}
 createNode(n){let mesh;if(n.kind==='core'){mesh=new THREE.Group();const core=new THREE.Mesh(new THREE.IcosahedronGeometry(.65,1),this.coreMat);mesh.add(core);for(let i=0;i<2;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(.95,.045,5,40),this.seedMat);ring.rotation.set(i?Math.PI/2:0,0,i?.4:0);mesh.add(ring);}const light=new THREE.PointLight(n.polarity<0?0xff89a9:0x00ffc3,15,18,2);mesh.add(light);}else{const geo=n.kind==='seed'?this.geos[2]:n.kind==='branch'?this.geos[0]:this.geos[n.shape]||this.geos[0];mesh=new THREE.Mesh(geo,n.kind==='seed'?this.seedMat:n.kind==='branch'?this.branchMat:this.mats[n.material]||this.mats[0]);mesh.castShadow=true;mesh.receiveShadow=true;}mesh.userData.nodeId=n.id;mesh.traverse(child=>child.userData.nodeId=n.id);mesh.position.set(n.x,n.y,n.z);mesh.scale.setScalar(n.size);this.scene.add(mesh);this.meshes.set(n.id,mesh);return mesh;}
 updateState(s,myId,dt){const ids=new Set();for(const n of s.nodes){ids.add(n.id);const mesh=this.meshes.get(n.id)||this.createNode(n);const t=1-Math.exp(-dt*16);mesh.position.lerp(new THREE.Vector3(n.x,n.y,n.z),t);mesh.rotation.set(n.rx||0,(n.ry||0)+(n.kind==='core'?this.time*.35:0),n.rz||0);if(n.kind==='seed')mesh.rotation.y=this.time;mesh.scale.setScalar(n.size*(n.kind==='seed'?1+Math.sin(this.time*3)*.12:1));}for(const[id,mesh]of this.meshes)if(!ids.has(id)){this.scene.remove(mesh);this.meshes.delete(id);}const players=new Set();for(const p of s.players){if(p.id===myId)continue;players.add(p.id);let mesh=this.avatars.get(p.id);if(!mesh){mesh=new THREE.Group();const mat=new THREE.MeshStandardMaterial({color:[0x00d992,0x65b9ff,0xffcc6b,0xdf9aff][p.color%4],emissive:[0x00d992,0x65b9ff,0xffcc6b,0xdf9aff][p.color%4],emissiveIntensity:.4,metalness:.7,roughness:.3});const body=new THREE.Mesh(new THREE.OctahedronGeometry(.55),mat);body.scale.set(1,.6,1);mesh.add(body);const ring=new THREE.Mesh(new THREE.TorusGeometry(.8,.035,4,24),mat);ring.rotation.x=Math.PI/2;mesh.add(ring);this.scene.add(mesh);this.avatars.set(p.id,mesh);}mesh.position.lerp(new THREE.Vector3(p.x,p.y-.7,p.z),1-Math.exp(-dt*12));mesh.rotation.y=p.yaw;}for(const[id,mesh]of this.avatars)if(!players.has(id)){this.scene.remove(mesh);this.avatars.delete(id);}
  for(const m of this.bondMeshes){this.scene.remove(m);m.geometry.dispose();m.material.dispose();}this.bondMeshes=[];const nodeMap=new Map(s.nodes.map(n=>[n.id,n]));for(const b of s.bonds){const a=nodeMap.get(b.a),n=nodeMap.get(b.b);if(!a||!n)continue;const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(a.x,a.y,a.z),new THREE.Vector3(n.x,n.y,n.z)]),new THREE.LineBasicMaterial({color:0x6ffff0,transparent:true,opacity:.7}));this.scene.add(line);this.bondMeshes.push(line);}
 }
 aim(){this.ray.setFromCamera(new THREE.Vector2(0,0),this.camera);const all=[...this.meshes.values(),...this.solid];const hit=this.ray.intersectObjects(all,true)[0];this.target=hit||null;if(hit?.object.userData.nodeId){const mesh=this.meshes.get(hit.object.userData.nodeId);this.selection.position.copy(mesh.position);this.selection.scale.copy(mesh.scale).multiplyScalar(1.1);this.selection.visible=true;}else this.selection.visible=false;return hit;}
 point(size=1){const hit=this.aim();if(hit){const p=hit.point.clone();if(hit.face){const normal=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);p.addScaledVector(normal,size*.6+.1);}return{x:p.x,y:p.y,z:p.z,target:hit.object.userData.nodeId};}const p=new THREE.Vector3();this.camera.getWorldDirection(p);p.multiplyScalar(10).add(this.camera.position);return{x:p.x,y:p.y,z:p.z};}
 burst(x,y,z,color=0x00ffb3,count=30){const rr=Math.random;const positions=new Float32Array(count*3),vel=[];for(let i=0;i<count;i++){positions[i*3]=x;positions[i*3+1]=y;positions[i*3+2]=z;vel.push(new THREE.Vector3((rr()-.5)*9,(rr()-.2)*9,(rr()-.5)*9));}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(positions,3));const mesh=new THREE.Points(geo,new THREE.PointsMaterial({color,size:.13,transparent:true,opacity:1}));this.scene.add(mesh);this.effects.push({mesh,vel,life:1.2,max:1.2});}
 pulse(x,y,z,color=0x00ffd0){const mesh=new THREE.Mesh(new THREE.SphereGeometry(1,20,12),new THREE.MeshBasicMaterial({color,wireframe:true,transparent:true,opacity:.65,depthWrite:false}));mesh.position.set(x,y,z);this.scene.add(mesh);this.effects.push({mesh,life:.7,max:.7,ring:true});}
 events(s,myId,cb){for(const e of s.events){if(e.id<=this.lastEvent)continue;this.lastEvent=e.id;if(e.type==='create')this.burst(e.x,e.y,e.z,e.color,12);if(['anchor','pulse','rain','grown','seed','erase'].includes(e.type)){this.pulse(e.x,e.y,e.z,e.type==='erase'?0xff9fcf:0x00ffc3);this.burst(e.x,e.y,e.z,e.type==='grown'?0xffa8dc:0x56ffc2,e.type==='pulse'?70:30);}if(e.type==='teleport'&&e.player===myId)this.camera.position.set(e.x,e.y,e.z);cb(e);}}
 render(s,myId,dt,playing){this.time+=dt;this.sky.position.copy(this.camera.position);this.clouds.rotation.y+=dt*.002;this.dust.rotation.y+=dt*.006;
  const night=s?.timeOfDay>.6,sunset=s?.timeOfDay>.35&&!night;const top=new THREE.Color(night?0x03081b:sunset?0x482d67:0x24466c),bottom=new THREE.Color(night?0x123249:sunset?0xc47691:0x91c9cc);this.skyMat.uniforms.top.value.lerp(top,dt*2);this.skyMat.uniforms.bottom.value.lerp(bottom,dt*2);this.scene.fog.color.lerp(bottom,dt*2);this.sun.intensity=night?.7:2.4;this.hemi.intensity=night?.85:1.6;this.bloom.strength=(this.settings.glow??80)/100*.7;
  if(s)this.updateState(s,myId,dt);if(!playing){const a=this.time*.045;this.camera.position.set(Math.sin(a)*52,28,Math.cos(a)*52);this.camera.lookAt(0,5,-5);this.hand.visible=false;this.selection.visible=false;}else{this.camera.rotation.set(this.pitch,this.yaw,0);this.hand.visible=true;this.hand.position.y=Math.sin(this.time*2)*.006;this.aim();}
  for(const ef of this.effects){ef.life-=dt;if(ef.ring){const v=1+(1-ef.life/ef.max)*22;ef.mesh.scale.setScalar(v);ef.mesh.material.opacity=Math.max(0,ef.life/ef.max)*.4;}else{const pos=ef.mesh.geometry.attributes.position;for(let i=0;i<ef.vel.length;i++){pos.array[i*3]+=ef.vel[i].x*dt;pos.array[i*3+1]+=ef.vel[i].y*dt;pos.array[i*3+2]+=ef.vel[i].z*dt;ef.vel[i].y-=dt*3;}pos.needsUpdate=true;ef.mesh.material.opacity=Math.max(0,ef.life/ef.max);}}
  this.effects=this.effects.filter(e=>{if(e.life>0)return true;this.scene.remove(e.mesh);e.mesh.geometry.dispose();e.mesh.material.dispose();return false;});this.composer.render();
 }
}
